files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8a9a;
  --focus: #f5c542;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  color: var(--text);
}

.card {
  background: var(--card);
  border-radius: 24px;
  padding: 32px 24px;
  max-width: 400px;
  width: 100%;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  color: var(--accent);
  text-transform: uppercase;
}

.elevator-display {
  display: flex;
  align-items: center;
  gap: 16px;
  background: #0f0f1a;
  border-radius: 16px;
  padding: 12px 24px;
  width: 100%;
  justify-content: center;
}

.floor-indicator {
  font-size: 3rem;
  font-weight: 700;
  color: var(--accent);
  min-width: 2ch;
  text-align: center;
  font-variant-numeric: tabular-nums;
}

.direction-indicator {
  font-size: 2rem;
  color: var(--muted);
  min-width: 2ch;
  text-align: center;
}

.door {
  width: 100%;
  height: 60px;
  background: #0f0f1a;
  border-radius: 12px;
  display: flex;
  overflow: hidden;
  position: relative;
  border: 2px solid #2a2a4a;
}

.door-left,
.door-right {
  flex: 1;
  background: var(--muted);
  transition: transform 0.3s ease;
}

.door-left {
  transform-origin: left;
}

.door-right {
  transform-origin: right;
}

.door.open .door-left {
  transform: translateX(-100%);
}

.door.open .door-right {
  transform: translateX(100%);
}

.panel {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  width: 100%;
}

.floor-btn {
  background: #0f0f1a;
  border: 2px solid #2a2a4a;
  color: var(--text);
  font-size: 1.5rem;
  font-weight: 600;
  padding: 16px 0;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, transform 0.1s;
  font-family: inherit;
  min-height: 56px;
}

.floor-btn:hover {
  background: #1e1e3a;
  border-color: var(--accent);
}

.floor-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.floor-btn:active {
  transform: scale(0.95);
  background: var(--accent);
}

.floor-btn.queued {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.status {
  font-size: 1rem;
  color: var(--muted);
  text-align: center;
  min-height: 1.5em;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .floor-indicator {
    font-size: 2.5rem;
  }
  .floor-btn {
    font-size: 1.25rem;
    padding: 12px 0;
  }
}

(function () {
  const floorDisplay = document.getElementById('floorDisplay');
  const directionDisplay = document.getElementById('directionDisplay');
  const statusText = document.getElementById('statusText');
  const door = document.getElementById('door');
  const floorButtons = document.querySelectorAll('.floor-btn');

  const MIN_FLOOR = 1;
  const MAX_FLOOR = 6;
  const MOVE_INTERVAL = 1000; // ms per floor
  const DOOR_OPEN_TIME = 1500; // ms

  let currentFloor = 1;
  let targetFloor = null;
  let queue = [];
  let moving = false;
  let doorsOpen = false;
  let moveTimer = null;
  let doorTimer = null;

  function updateDisplay() {
    floorDisplay.textContent = currentFloor;
    if (moving && targetFloor !== null) {
      directionDisplay.textContent = targetFloor > currentFloor ? '▲' : '▼';
    } else {
      directionDisplay.textContent = '—';
    }
  }

  function updateQueueUI() {
    floorButtons.forEach(btn => {
      const floor = parseInt(btn.dataset.floor, 10);
      btn.classList.toggle('queued', queue.includes(floor));
    });
  }

  function setStatus(msg) {
    statusText.textContent = msg;
  }

  function openDoors() {
    if (doorsOpen) return;
    doorsOpen = true;
    door.classList.add('open');
    doorTimer = setTimeout(() => {
      door.classList.remove('open');
      doorsOpen = false;
      doorTimer = null;
      processQueue();
    }, DOOR_OPEN_TIME);
  }

  function moveToNext() {
    if (queue.length === 0) {
      moving = false;
      targetFloor = null;
      updateDisplay();
      setStatus('Idle. Press a floor button.');
      return;
    }

    targetFloor = queue[0];
    if (targetFloor === currentFloor) {
      queue.shift();
      updateQueueUI();
      openDoors();
      setStatus('Doors open at floor ' + currentFloor);
      return;
    }

    moving = true;
    updateDisplay();
    setStatus('Moving to floor ' + targetFloor);

    moveTimer = setInterval(() => {
      if (currentFloor < targetFloor) {
        currentFloor++;
      } else if (currentFloor > targetFloor) {
        currentFloor--;
      }
      updateDisplay();

      if (currentFloor === targetFloor) {
        clearInterval(moveTimer);
        moveTimer = null;
        moving = false;
        queue.shift();
        updateQueueUI();
        openDoors();
        setStatus('Doors open at floor ' + currentFloor);
      }
    }, MOVE_INTERVAL);
  }

  function processQueue() {
    if (queue.length === 0) {
      setStatus('Idle. Press a floor button.');
      moving = false;
      targetFloor = null;
      updateDisplay();
      return;
    }
    if (!moving && !doorsOpen) {
      moveToNext();
    }
  }

  function addToQueue(floor) {
    if (floor === currentFloor && !moving && !doorsOpen) {
      // already here, just open doors
      openDoors();
      setStatus('Doors open at floor ' + currentFloor);
      return;
    }
    if (!queue.includes(floor)) {
      queue.push(floor);
      updateQueueUI();
    }
    if (!moving && !doorsOpen) {
      processQueue();
    }
  }

  floorButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      const floor = parseInt(btn.dataset.floor, 10);
      addToQueue(floor);
    });
  });

  // Initialize
  updateDisplay();
  updateQueueUI();
  setStatus('Idle. Press a floor button.');
})();
